-- Add Q-Former method, introduced in arXiv 2301.12597. The source paper
-- gets the source evidence row (Introduced banner); citers are linked by
-- link_papers_by_source_citations.py and the hourly reference backfill.

INSERT INTO methods (
    slug,
    name,
    full_name,
    description,
    keywords,
    area_id,
    introduced_year,
    source_paper_id,
    source_url,
    source_title,
    code_snippet_url,
    image_url,
    image_credit
)
VALUES (
    'q-former',
    'Q-Former',
    'Querying Transformer (Q-Former)',
    'The Querying Transformer (Q-Former) is a lightweight module, introduced in BLIP-2, that bridges a frozen image encoder and a frozen large language model. A fixed set of learnable query embeddings (32 in BLIP-2) interacts with the image features through cross-attention and with each other through self-attention, so the Q-Former extracts a small number of visual tokens regardless of image resolution. It is pre-trained in two stages: first with image-text contrastive, image-grounded text generation and image-text matching objectives against the frozen image encoder, then by projecting its outputs into the frozen LLM''s input space as soft visual prompts for generative learning. With this design BLIP-2 outperformed Flamingo-80B by 8.7% on zero-shot VQAv2 with 54x fewer trainable parameters. The Q-Former was reused by vision-language models such as [InstructBLIP](/paper/2305.06500) and [MiniGPT-4](/paper/2304.10592); the [Perceiver Resampler](/methods/perceiver-resampler) is a related learned-query connector.',
    'Q-Former, QFormer, Querying Transformer',
    (
        SELECT id
        FROM areas
        WHERE name = 'Vision'
        LIMIT 1
    ),
    2023,
    (
        SELECT id
        FROM papers
        WHERE arxiv_id = '2301.12597'
        ORDER BY is_latest_version DESC, id DESC
        LIMIT 1
    ),
    NULL,
    'BLIP-2: Bootstrapping Language-Image Pre-training with Frozen Image Encoders and Large Language Models',
    'https://github.com/salesforce/LAVIS/blob/main/lavis/models/blip2_models/Qformer.py',
    NULL,
    '[BLIP-2: Bootstrapping Language-Image Pre-training with Frozen Image Encoders and Large Language Models](/paper/2301.12597)'
)
ON CONFLICT (slug) DO UPDATE
SET
    name = EXCLUDED.name,
    full_name = EXCLUDED.full_name,
    description = EXCLUDED.description,
    keywords = EXCLUDED.keywords,
    area_id = EXCLUDED.area_id,
    introduced_year = EXCLUDED.introduced_year,
    source_paper_id = EXCLUDED.source_paper_id,
    source_url = EXCLUDED.source_url,
    source_title = EXCLUDED.source_title,
    code_snippet_url = EXCLUDED.code_snippet_url,
    image_url = EXCLUDED.image_url,
    image_credit = EXCLUDED.image_credit,
    updated_at = CURRENT_TIMESTAMP;

INSERT INTO paper_methods (paper_id, method_id)
SELECT source_paper_id, id
FROM methods
WHERE slug = 'q-former'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id) DO NOTHING;

INSERT INTO paper_method_evidence (paper_id, method_id, evidence_type)
SELECT source_paper_id, id, 'source'
FROM methods
WHERE slug = 'q-former'
  AND source_paper_id IS NOT NULL
ON CONFLICT (paper_id, method_id, evidence_type) DO UPDATE SET
    last_seen_at = now();

